// Generates `sury/protobuf/wkt` - the well-known types a generated file imports rather
// than expecting beside it - from the upstream protos buf ships, with this
// generator, and S.res's `Protobuf`, which binds them for ReScript. The output
// is committed; `test/cli.ts` fails when it is stale.
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { decodeFileDescriptorSet, type FileDescriptorProto } from "../src/descriptor";
import { generate } from "../src/plugin";
import { buildRegistry } from "../src/model";
import { resModules, moduleOf } from "../src/res";
import { wktFiles } from "../src/shared";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const buf = join(root, "node_modules/.bin/buf");

export const wktSet = () => {
  const dir = mkdtempSync(join(tmpdir(), "sury-wkt-"));
  try {
    writeFileSync(join(dir, "buf.yaml"), "version: v2\n");
    writeFileSync(join(dir, "wkt.proto"), `syntax = "proto3";\n${[...wktFiles].map((file) => `import "${file}";\n`).join("")}`);
    execFileSync(buf, ["build", dir, "-o", join(dir, "set.binpb")], { stdio: ["ignore", "ignore", "inherit"] });
    return decodeFileDescriptorSet(new Uint8Array(readFileSync(join(dir, "set.binpb"))));
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
};

const wktIndex = (): string =>
  [
    "// @generated by protoc-gen-sury: the well-known types, as `sury/protobuf/wkt`.",
    "/* eslint-disable */",
    "",
    'import type * as S from "sury";',
    "",
    ...[...wktFiles].map((file) => `export * from "./${file.replace(/\.proto$/, "_pb.js")}";`),
    "",
    "/** A JSON value, what a `google.protobuf.Value` holds. */",
    "export type JsonValue = S.Infer<typeof S.json>;",
    "",
    "/** A JSON object: how a `google.protobuf.Struct` field is held. */",
    "export type JsonObject = { [key: string]: JsonValue };",
    "",
  ].join("\n");

export const generateWkt = (set: { file: FileDescriptorProto[] }): { name: string; content: string }[] => {
  const response = generate({ fileToGenerate: [...wktFiles], parameter: "target=ts,import_extension=js", protoFile: set.file }, "");
  if (response.error !== undefined) throw new Error(response.error);
  return [...response.file, { name: "index.ts", content: wktIndex() }];
};

export const generateWktRes = (set: { file: FileDescriptorProto[] }): string => {
  const registry = buildRegistry(set.file);
  const ordered: string[] = [];
  const visit = (name: string) => {
    if (ordered.includes(name) || !wktFiles.has(name)) return;
    for (const dependency of registry.files.get(name)!.proto.dependency) visit(dependency);
    ordered.push(name);
  };
  for (const name of wktFiles) visit(name);
  const bodies = ordered.map(
    (name) => `// ${name}\n\n${resModules(registry.files.get(name)!, { s: "", wellKnownModule: (desc) => moduleOf(desc), bind: "sury/protobuf/wkt" }).body}`,
  );
  return (
    `${regionStart}\n` +
    "/** The `google.protobuf` well-known types, each a module holding its type `t` and its `schema`. */\n" +
    `module Protobuf = {\n${bodies.join("\n").replace(/^(?=.)/gm, "  ")}}\n${regionEnd}\n`
  );
};

const regionStart = "// @generated by protoc-gen-sury: the well-known types, bound to sury/protobuf/wkt.";
const regionEnd = "// @generated end";

export const withWktRes = (source: string, region: string): string => {
  const start = source.indexOf(regionStart);
  if (start === -1) return `${source.replace(/\n*$/, "\n\n")}${region}`;
  const end = source.indexOf(`\n${regionEnd}\n`, start);
  if (end === -1) throw new Error(`S.res opens "${regionStart}" and never closes it`);
  return `${source.slice(0, start)}${region}${source.slice(end + regionEnd.length + 2)}`;
};

export const sRes = join(root, "../sury/src/S.res");

